#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.78-live-text-brand-search-fix.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode('')))
for rel,spec in payload.items():
 p=root/rel; data=p.read_bytes()
 if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected grid-3dot 1.1.78 baseline: "+rel)
 lines=data.decode("utf-8").splitlines(keepends=True)
 for i1,i2,text in reversed(spec["ops"]): lines[i1:i2]=text.splitlines(keepends=True)
 p.write_text("".join(lines),encoding="utf-8")
p=(root/"shishalove-app-bridge.php").read_text();m=(root/"assets/merchant.js").read_text();c=(root/"assets/bridge.css").read_text()
for token in ["Version: 1.1.78","slb_merchant_search_brand_terms_178","slb_merchant_search_brand_product_ids_178","scheduleLiveTextSearch","merchantSearchRequest","Searching…","runLiveTextSearch(value,started,generation)","data-product-view","slm-overflow-icon"]:
 if token not in p+m+c: raise SystemExit("missing live-search fix token: "+token)
if "setTimeout(function(){loadLiveCatalog(false);},0)" in m: raise SystemExit("whole-catalog live search prefetch still active")
if "Version: 1.1.79" in p: raise SystemExit("version bump forbidden")
print("Bridge 1.1.78 live text + brand search master fix applied; version intentionally unchanged")
